import { Title } from "@solidjs/meta";
import { createAsync, useAction, useSubmission } from "@solidjs/router";
import { createSignal, Show } from "solid-js";
import { createStore } from "solid-js/store";
import {
  readContact,
  validateContact,
  type ContactErrors,
  type ContactResult,
  type ContactValues
} from "~/lib/contact";
import { getContactSubmission, sendContact } from "~/lib/contact-server";

export default function Contact() {
  const submission = createAsync(() => getContactSubmission());
  return (
    <>
      <Title>Contact | Bookshelf</Title>
      <h1>Contact</h1>
      <Show when={submission() !== undefined}>
        <ContactForm initial={submission() ?? undefined} />
      </Show>
    </>
  );
}

const empty: ContactValues = { name: "", email: "", message: "" };

function ContactForm(props: { initial?: ContactResult }) {
  const initial = props.initial;
  const [values, setValues] = createStore<ContactValues>(
    initial && !initial.success ? { ...initial.values } : { ...empty }
  );
  const [errors, setErrors] = createStore<ContactErrors>(initial?.errors ?? {});
  const [success, setSuccess] = createSignal(initial?.success ?? "");
  const send = useAction(sendContact);
  const sending = useSubmission(sendContact);

  const onSubmit = async (event: SubmitEvent) => {
    event.preventDefault();
    const form = event.currentTarget as HTMLFormElement;
    const sent = readContact(new FormData(form));
    setSuccess("");
    const found = validateContact(sent);
    setErrors({ name: found.name, email: found.email, message: found.message });
    if (Object.keys(found).length) return;
    try {
      const result = await send(sent);
      setErrors({ name: result.errors.name, email: result.errors.email, message: result.errors.message });
      if (result.success) {
        setSuccess(result.success);
        setValues({ ...empty });
      }
    } catch {
      setErrors({ message: "Your message could not be sent. Please try again." });
    }
  };

  const field = (name: keyof ContactValues) => ({
    id: `contact-${name}`,
    name,
    value: values[name],
    "aria-invalid": errors[name] ? ("true" as const) : undefined,
    "aria-describedby": errors[name] ? `contact-${name}-error` : undefined,
    onInput: (event: InputEvent & { currentTarget: HTMLInputElement | HTMLTextAreaElement }) =>
      setValues(name, event.currentTarget.value)
  });

  const error = (name: keyof ContactValues) => (
    <Show when={errors[name]}>
      <p class="error" id={`contact-${name}-error`}>
        {errors[name]}
      </p>
    </Show>
  );

  return (
    <>
      <Show when={success()}>
        <p class="success" role="status">
          {success()}
        </p>
      </Show>
      <form method="post" action="/contact" novalidate onSubmit={onSubmit} class="contact-form">
        <div class="field">
          <label for="contact-name">Name</label>
          <input type="text" autocomplete="name" {...field("name")} />
          {error("name")}
        </div>
        <div class="field">
          <label for="contact-email">Email</label>
          <input type="email" autocomplete="email" {...field("email")} />
          {error("email")}
        </div>
        <div class="field">
          <label for="contact-message">Message</label>
          <textarea rows={6} {...field("message")} />
          {error("message")}
        </div>
        <button type="submit" disabled={sending.pending}>
          Send
        </button>
      </form>
    </>
  );
}
EOF
