import { query } from "@solidjs/router";
import { getRequestEvent } from "solid-js/web";
import { submitContact, type ContactResult, type ContactValues } from "./contact";

/** The outcome of a no-JS POST to /contact, if this request was one. */
export const getContactSubmission = query(async () => {
  "use server";
  return getRequestEvent()?.locals.contact ?? null;
}, "contact-submission");

/** Checks a message sent from the browser. Nothing is stored. */
export async function sendContact(values: ContactValues): Promise<ContactResult> {
  "use server";
  return submitContact({
    name: String(values?.name ?? ""),
    email: String(values?.email ?? ""),
    message: String(values?.message ?? "")
  });
}
